import json,sys
d=json.load(sys.stdin)
for i in d['items']:
    for r in i.get('results',[]):
        if r.get('result')=='fail':
            res=r.get('resources',[{}])[0]
            print(f\"{i['metadata']['namespace']:12} {r['policy']:32} {res.get('kind','?')}/{res.get('name','?')}\")
"

